"""Executable behavioral references for batch 16."""
import argparse,sys
from pathlib import Path
import numpy as np,pandas as pd
TOOLS=Path(__file__).resolve().parents[2]/'tools';sys.path.insert(0,str(TOOLS))
from batch08_reference import js
from batch11_reference import prediction_parallel
from batch13_reference import service_fanin

def valid(d,cols,idc,cats=()):
 if set(cols)-set(d):raise ValueError('columns')
 if not d[idc].is_unique or d[idc].astype(str).str.strip().eq('').any():raise ValueError('id')
 for c in cats:
  if d[c].isna().any() or d[c].astype(str).str.strip().eq('').any():raise ValueError('category')
 nums=[c for c in cols if c not in {idc,*cats}]
 for c in nums:d[c]=pd.to_numeric(d[c],errors='coerce')
 if not np.isfinite(d[nums].to_numpy(float)).all():raise ValueError('nonfinite')

def sports_multiview(data,out):
 d=pd.read_csv(data/'data.csv');cols=['player_id','team','position','games_played','points_per_game','assists_per_game','rebounds_per_game','minutes_per_game','age','experience_years','salary_millions','field_goal_pct','three_point_pct','free_throw_pct'];valid(d,cols,'player_id',['team','position']);d=d[cols].sort_values('player_id');d.to_csv(out/'players_clean.csv',index=False);p=d[['player_id','points_per_game','assists_per_game','rebounds_per_game','minutes_per_game']].copy();p['production_index']=p.points_per_game+p.assists_per_game+p.rebounds_per_game;p['production_per_minute']=np.where(p.minutes_per_game>0,p.production_index/p.minutes_per_game,0);p.to_csv(out/'performance_features.csv',index=False);s=d[['player_id','field_goal_pct','three_point_pct','free_throw_pct']].copy();s['shooting_index']=s[['field_goal_pct','three_point_pct','free_throw_pct']].mean(axis=1);s['weighted_shooting_index']=.5*s.field_goal_pct+.3*s.three_point_pct+.2*s.free_throw_pct;s.to_csv(out/'shooting_features.csv',index=False);c=d[['player_id','team','position','games_played','age','experience_years','salary_millions']].copy();c['age_band']=pd.cut(c.age,[0,24,29,34,np.inf],labels=['<=24','25-29','30-34','35+']).astype(str);c['salary_band']=pd.cut(c.salary_millions,[-np.inf,5,10,20,np.inf],labels=['<=5','5-10','10-20','20+']).astype(str);c.to_csv(out/'context_features.csv',index=False);m=p.merge(s,on='player_id',validate='one_to_one').merge(c,on='player_id',validate='one_to_one');m.to_csv(out/'analysis_table.csv',index=False)
 team=m.groupby('team',as_index=False).agg(player_count=('player_id','size'),mean_production=('production_index','mean'),mean_shooting=('shooting_index','mean'),mean_salary=('salary_millions','mean')).sort_values('team');team.to_csv(out/'team_summary.csv',index=False);pos=m.groupby('position',as_index=False).agg(player_count=('player_id','size'),mean_production=('production_index','mean'),mean_shooting=('shooting_index','mean'),mean_minutes=('minutes_per_game','mean')).sort_values('position');pos.to_csv(out/'position_summary.csv',index=False);age=m.groupby('age_band',as_index=False).agg(player_count=('player_id','size'),mean_production=('production_index','mean'),mean_shooting=('shooting_index','mean'),mean_salary=('salary_millions','mean')).sort_values('age_band');age.to_csv(out/'age_summary.csv',index=False);salary=m.groupby('salary_band',as_index=False).agg(player_count=('player_id','size'),mean_production=('production_index','mean'),mean_shooting=('shooting_index','mean'),mean_experience=('experience_years','mean')).sort_values('salary_band');salary.to_csv(out/'salary_summary.csv',index=False);js(out/'sports_report.json',{'players':len(m),'team_players':int(team.player_count.sum()),'position_players':int(pos.player_count.sum()),'age_players':int(age.player_count.sum()),'salary_players':int(salary.player_count.sum()),'teams':len(team),'positions':len(pos),'age_bands':len(age),'salary_bands':len(salary)})

def position_linear(data,out):
 d=pd.read_csv(data/'data.csv');cols=['player_id','team','position','games_played','points_per_game','assists_per_game','rebounds_per_game','minutes_per_game','age','experience_years','salary_millions'];valid(d,cols,'player_id',['team','position']);clean=d[cols].sort_values('player_id');clean.to_csv(out/'players_clean.csv',index=False);f=clean.copy();f['production_index']=f.points_per_game+f.assists_per_game+f.rebounds_per_game;f['production_per_minute']=np.where(f.minutes_per_game>0,f.production_index/f.minutes_per_game,0);f['value_index']=f.production_index/(f.salary_millions+1);f.to_csv(out/'player_features.csv',index=False);s=f.groupby('position',as_index=False).agg(player_count=('player_id','size'),mean_production=('production_index','mean'),mean_per_minute=('production_per_minute','mean'),mean_value=('value_index','mean'),mean_experience=('experience_years','mean')).sort_values('position');s.to_csv(out/'position_summary.csv',index=False);rank=s.sort_values(['mean_production','mean_value','position'],ascending=[False,False,True]).reset_index(drop=True);rank.insert(1,'rank',np.arange(1,len(rank)+1));rank.to_csv(out/'position_ranking.csv',index=False);js(out/'position_report.json',{'players':int(rank.player_count.sum()),'positions':len(rank),'top_position':rank.iloc[0].position,'top_mean_production':rank.iloc[0].mean_production})

def trip_fanout(data,out):
 d=pd.read_csv(data/'data.csv');cols=['trip_id','route','vehicle_type','departure_hour','distance_km','passengers','fare_amount','delay_minutes','day_of_week','is_holiday','weather_condition'];valid(d,cols,'trip_id',['route','vehicle_type','day_of_week','weather_condition']);clean=d[cols].sort_values('trip_id').copy();clean['passenger_km']=clean.distance_km*clean.passengers;clean['on_time']=(clean.delay_minutes<=5).astype(int);clean['time_period']=pd.cut(clean.departure_hour,[-1,5,11,17,23],labels=['night','morning','afternoon','evening']).astype(str);clean.to_csv(out/'trips_prepared.csv',index=False);clean.groupby('route',as_index=False).agg(trip_count=('trip_id','size'),total_passenger_km=('passenger_km','sum'),mean_delay=('delay_minutes','mean'),on_time_rate=('on_time','mean')).sort_values('route').to_csv(out/'route_operations.csv',index=False);clean.groupby('vehicle_type',as_index=False).agg(trip_count=('trip_id','size'),mean_passengers=('passengers','mean'),mean_fare=('fare_amount','mean'),mean_delay=('delay_minutes','mean')).sort_values('vehicle_type').to_csv(out/'vehicle_operations.csv',index=False);clean.groupby('time_period',as_index=False).agg(trip_count=('trip_id','size'),total_passenger_km=('passenger_km','sum'),mean_delay=('delay_minutes','mean'),on_time_rate=('on_time','mean')).sort_values('time_period').to_csv(out/'period_operations.csv',index=False)

RUNNERS={'040_sports_statistical_visualization_cleaning_v2':sports_multiview,'047_sports_visualization_integration_features':position_linear,'065_transportation_integration_extra':trip_fanout,'069_transportation_prediction_cleaning_integration':prediction_parallel,'090_transportation_statistical_visualization_integration_v2':service_fanin}
if __name__=='__main__':
 p=argparse.ArgumentParser();p.add_argument('--data-dir',type=Path,required=True);p.add_argument('--output-dir',type=Path,required=True);x=p.parse_args();x.output_dir.mkdir(parents=True,exist_ok=True);RUNNERS[Path(__file__).resolve().parent.name](x.data_dir,x.output_dir)
